const STAGES = ['signed_up', 'workflow_deployed', 'first_successful_run'];
const byClient = {};
for (const it of items) {
  const c = it.json['Client ID'] || it.json.client_id;
  const stage = it.json['Stage'] || it.json.stage;
  const ts = it.json['Timestamp'] || it.json.timestamp;
  if (!c || !stage || !ts) continue;
  byClient[c] = byClient[c] || {};
  byClient[c][stage] = new Date(ts).getTime();
}
const gapHours = { 'signed_up->workflow_deployed': [], 'workflow_deployed->first_successful_run': [] };
for (const c of Object.keys(byClient)) {
  const t = byClient[c];
  if (t.signed_up && t.workflow_deployed) {
    gapHours['signed_up->workflow_deployed'].push((t.workflow_deployed - t.signed_up) / 3600000);
  }
  if (t.workflow_deployed && t.first_successful_run) {
    gapHours['workflow_deployed->first_successful_run'].push((t.first_successful_run - t.workflow_deployed) / 3600000);
  }
}
const avg = arr => arr.length ? Math.round((arr.reduce((a,b) => a+b, 0) / arr.length) * 10) / 10 : null;
const avgGap1 = avg(gapHours['signed_up->workflow_deployed']);
const avgGap2 = avg(gapHours['workflow_deployed->first_successful_run']);
const stages = [
  { name: 'signed_up->workflow_deployed', avg_hours: avgGap1 },
  { name: 'workflow_deployed->first_successful_run', avg_hours: avgGap2 }
].filter(s => s.avg_hours !== null);
stages.sort((a, b) => b.avg_hours - a.avg_hours);
const slowest = stages[0] || { name: 'insufficient_data', avg_hours: 0 };
return [{ json: {
  clients_analyzed: Object.keys(byClient).length,
  stage_averages: stages,
  slowest_stage: slowest.name,
  slowest_stage_avg_hours: slowest.avg_hours
} }];
